+package ai.unifiedprocess.petclinic.vet.domain;
+
+import org.jooq.DSLContext;
+import org.springframework.stereotype.Repository;
+import org.springframework.transaction.annotation.Transactional;
+
+import java.util.stream.Stream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.*;
+import static org.jooq.Records.mapping;
+import static org.jooq.impl.DSL.multiset;
+import static org.jooq.impl.DSL.select;
+
+@Repository
+@Transactional(readOnly = true)
+public class VetRepository {
+    private final DSLContext dsl;
+
+    public VetRepository(DSLContext dsl) {
+        this.dsl = dsl;
+    }
+
+    public Stream<Vet> findPage(int offset, int limit) {
+        return dsl.select(VETS.ID, VETS.FIRST_NAME, VETS.LAST_NAME,
+                        multiset(select(SPECIALTIES.ID, SPECIALTIES.NAME)
+                                .from(SPECIALTIES)
+                                .join(VET_SPECIALTIES).on(VET_SPECIALTIES.SPECIALTY_ID.eq(SPECIALTIES.ID))
+                                .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
+                                .orderBy(SPECIALTIES.NAME.asc())
+                        ).convertFrom(rows -> rows.map(mapping(Specialty::new))))
+                .from(VETS)
+                .orderBy(VETS.LAST_NAME.asc(), VETS.FIRST_NAME.asc(), VETS.ID.asc())
+                .offset(offset).limit(limit)
+                // Materialize the bounded page while the read transaction is open.
+                .fetch(mapping(Vet::new)).stream();
+    }
+
+    public int count() {
+        return dsl.fetchCount(VETS);
+    }
+}
