+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Specialty;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Collectors;
+import java.util.stream.Stream;
+
+/** UC-002: Browse the clinic's veterinarians and their specialties. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+    private final transient VetRepository repository;
+
+    public VeterinariansView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+        Grid<Vet> grid = new Grid<>();
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.addColumn(Vet::firstName).setHeader("First Name").setAutoWidth(true);
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setAutoWidth(true);
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : vet.specialties().stream()
+                .map(Specialty::name).collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setFlexGrow(2);
+        grid.setSizeFull();
+        grid.setItems(this::fetch, query -> count());
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (DataAccessException exception) {
+            ApplicationErrorView.showError(exception, "Unable to load veterinarians. Please try again later.");
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            ApplicationErrorView.showError(exception, "Unable to load veterinarians. Please try again later.");
+            return 0;
+        }
+    }
+}
