+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.jooq.impl.DSL;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.*;
+import static org.junit.jupiter.api.Assertions.*;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationShowsNamesAndOrderedSpecialtiesWithoutAuthentication() {
+        navigate(WelcomeView.class);
+        var link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(), "Veterinarians menu link");
+        UI.getCurrent().navigate(link.getPath());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        var tester = test(grid());
+        assertEquals(6, tester.size());
+        assertEquals("First Name", tester.getHeaderCell(0));
+        assertEquals("Last Name", tester.getHeaderCell(1));
+        assertEquals("Specialties", tester.getHeaderCell(2));
+        assertEquals("James", tester.getCellText(0, 0));
+        assertEquals("Carter", tester.getCellText(0, 1));
+        assertEquals("none", tester.getCellText(0, 2));
+        assertEquals("Linda", tester.getCellText(1, 0));
+        assertEquals("Douglas", tester.getCellText(1, 1));
+        assertEquals("dentistry, surgery", tester.getCellText(1, 2));
+        assertEquals("radiology", tester.getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVeterinariansShowsAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VeterinariansView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesOnlyRequestedChunksWithStableOrdering() {
+        for (int index = 0; index < 125; index++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Vet", "Extra%03d".formatted(index)).execute();
+        }
+        navigate(VeterinariansView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(131, provider.size(new Query<>()));
+        var first = provider.fetch(new Query<>(0, 7, List.of(), null, null)).toList();
+        var next = provider.fetch(new Query<>(7, 13, List.of(), null, null)).toList();
+        assertEquals(7, first.size());
+        assertEquals(13, next.size());
+        assertEquals(List.of("Carter", "Douglas", "Extra000", "Extra001", "Extra002", "Extra003", "Extra004"),
+                first.stream().map(Vet::lastName).toList());
+        assertEquals(IntStream.range(5, 18).mapToObj(i -> "Extra%03d".formatted(i)).toList(),
+                next.stream().map(Vet::lastName).toList());
+        assertEquals(1, provider.fetch(new Query<>(130, 13, List.of(), null, null)).count());
+        assertEquals(0, provider.fetch(new Query<>(131, 13, List.of(), null, null)).count());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorAndRemovesGrid() {
+        navigate(VeterinariansView.class);
+        var provider = grid().getDataProvider();
+        dsl.alterTable(VETS).renameTo(DSL.name("unavailable_vets")).execute();
+        assertEquals(0, provider.size(new Query<>()));
+        assertErrorScreen();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterFetchFailureShowsApplicationErrorAndRemovesLoadedRows() {
+        navigate(VeterinariansView.class);
+        var provider = grid().getDataProvider();
+        assertEquals(2, provider.fetch(new Query<>(0, 2, List.of(), null, null)).count());
+        dsl.alterTable(SPECIALTIES).renameTo(DSL.name("unavailable_specialties")).execute();
+        assertEquals(0, provider.fetch(new Query<>(2, 2, List.of(), null, null)).count());
+        assertErrorScreen();
+    }
+
+    private void assertErrorScreen() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(), "Application error view");
+        assertDoesNotThrow(() -> find(MainLayout.class).single(), "Navigation shell survives failure");
+        assertDoesNotThrow(() -> find(Paragraph.class)
+                .withText("Unable to load veterinarians. Please try again later.").single(), "Safe error message");
+        assertTrue(find(Grid.class).all().isEmpty());
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return (Grid<Vet>) assertDoesNotThrow(() -> find(Grid.class).single(), "Veterinarians grid");
+    }
+}
